import{_ as a,o as t,c as o,a5 as r}from"./chunks/framework.DOB-AMqW.js";const m=JSON.parse('{"title":"Card Nest Data Collection","description":"Standalone summary of Card Nest data practices.","frontmatter":{"title":"Card Nest Data Collection","description":"Standalone summary of Card Nest data practices.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/card-nest.md","filePath":"data-collection/card-nest.md"}'),s={name:"data-collection/card-nest.md"};function i(n,e,l,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="card-nest-data-collection" tabindex="-1">Card Nest Data Collection <a class="header-anchor" href="#card-nest-data-collection" aria-label="Permalink to &quot;Card Nest Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> August 1, 2026</p><h2 id="data-stored-locally" tabindex="-1">Data stored locally <a class="header-anchor" href="#data-stored-locally" aria-label="Permalink to &quot;Data stored locally&quot;">​</a></h2><p>Card Nest stores card information, optional encrypted full card numbers and CVVs, transactions, receipts, income, budgets, categories, payment sources, balances, loans, EMIs, reminders, profile details, preferences, and report data in local SQLite storage.</p><p>The application PIN is stored only as a salted PBKDF2 hash. Android handles biometric verification without providing biometric templates to Card Nest.</p><h2 id="data-collected-by-the-developer" tabindex="-1">Data collected by the developer <a class="header-anchor" href="#data-collected-by-the-developer" aria-label="Permalink to &quot;Data collected by the developer&quot;">​</a></h2><p>Card Nest has no account, developer cloud, analytics, advertising, crash reporting, or tracking service. The developer does not receive app database contents, financial records, receipts, PINs, or usage data.</p><p>If you email support, the developer receives only the information you choose to include in that message.</p><h2 id="data-processed-outside-local-sqlite" tabindex="-1">Data processed outside local SQLite <a class="header-anchor" href="#data-processed-outside-local-sqlite" aria-label="Permalink to &quot;Data processed outside local SQLite&quot;">​</a></h2><ul><li>Android can store masked reminder content containing a card nickname, last digits, amount, and date when notifications are enabled.</li><li>Google may receive normal connection metadata when Google Fonts resources are requested.</li><li>A file or sharing provider you choose receives encrypted backups or readable report exports sent to it.</li><li>The camera and system photo picker provide receipt images only after your action and permission or selection.</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Camera, selected photos, notifications, biometrics, file access, and internet access are used only for their corresponding features. The reviewed app does not require location, contacts, phone, SMS, or broad gallery access.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',14)])])}const u=a(s,[["render",i]]);export{m as __pageData,u as default};
